// Lesson content: loads content/units/<unit>/<lesson>.json (generated by `npm run build:lessons`) and checks its shape
// at runtime without a schema library. A bad file fails loudly in tests and in the build instead of crashing a lesson.

import falling1 from "../../../content/units/falling/falling-1.json" with { type: "json" };
import falling2 from "../../../content/units/falling/falling-2.json" with { type: "json" };
import falling3 from "../../../content/units/falling/falling-3.json" with { type: "json" };
import rising1 from "../../../content/units/rising/rising-1.json" with { type: "json" };
import rising2 from "../../../content/units/rising/rising-2.json" with { type: "json" };
import lists1 from "../../../content/units/lists/lists-1.json" with { type: "json" };
import lists2 from "../../../content/units/lists/lists-2.json" with { type: "json" };
import nonfinal1 from "../../../content/units/nonfinal/nonfinal-1.json" with { type: "json" };
import nonfinal2 from "../../../content/units/nonfinal/nonfinal-2.json" with { type: "json" };
import tags1 from "../../../content/units/tags/tags-1.json" with { type: "json" };
import tags2 from "../../../content/units/tags/tags-2.json" with { type: "json" };
import tags3 from "../../../content/units/tags/tags-3.json" with { type: "json" };
import { levelsForFallingTag, levelsForGroup, levelsForNonFinalGroup, levelsForRisingGroup } from "../intonation/buildLesson.ts";
import type { PatternId, Sentence } from "../intonation/types.ts";

export interface LessonContent {
  id: string;
  unit: string;
  sentences: Sentence[];
}

const PATTERNS: readonly PatternId[] = ["2-3-1", "2-3-2", "2-3", "3-1"];

/** Every file you add under content/units needs one line here (a test checks every lesson in UNITS has content). */
const REGISTRY: Record<string, unknown> = {
  "falling/falling-1": falling1,
  "falling/falling-2": falling2,
  "falling/falling-3": falling3,
  "rising/rising-1": rising1,
  "rising/rising-2": rising2,
  "lists/lists-1": lists1,
  "lists/lists-2": lists2,
  "nonfinal/nonfinal-1": nonfinal1,
  "nonfinal/nonfinal-2": nonfinal2,
  "tags/tags-1": tags1,
  "tags/tags-2": tags2,
  "tags/tags-3": tags3,
};

const isObj = (x: unknown): x is Record<string, unknown> => typeof x === "object" && x !== null && !Array.isArray(x);
const isStr = (x: unknown): x is string => typeof x === "string" && x.length > 0;

/** Everything wrong with a lesson file, as readable lines. Empty means valid. */
export function lessonProblems(data: unknown): string[] {
  const out: string[] = [];
  if (!isObj(data)) return ["lesson is not an object"];
  if (!isStr(data.id)) out.push("lesson.id missing");
  if (!isStr(data.unit)) out.push("lesson.unit missing");
  if (!Array.isArray(data.sentences) || data.sentences.length === 0) return [...out, "lesson.sentences must be a non-empty array"];

  const seen = new Set<string>();
  data.sentences.forEach((s: unknown, i: number) => {
    const at = `sentence[${i}]`;
    if (!isObj(s)) return void out.push(`${at} is not an object`);
    const id = isStr(s.id) ? s.id : at;
    if (!isStr(s.id)) out.push(`${at}.id missing`);
    else if (seen.has(s.id)) out.push(`${id}: duplicate id`);
    else seen.add(s.id);
    if (!isStr(s.text)) out.push(`${id}.text missing`);
    if (!isStr(s.kind)) out.push(`${id}.kind missing`);
    if (!isObj(s.note) || !isStr(s.note.en) || !isStr(s.note.th)) out.push(`${id}.note must be { en, th }`);
    if (!Array.isArray(s.groups) || s.groups.length === 0) return void out.push(`${id}.groups must be a non-empty array`);

    s.groups.forEach((g: unknown, gi: number) => {
      const gat = `${id}.groups[${gi}]`;
      if (!isObj(g)) return void out.push(`${gat} is not an object`);
      if (!PATTERNS.includes(g.pattern as PatternId)) out.push(`${gat}.pattern "${String(g.pattern)}" unknown`);
      if (!Array.isArray(g.words) || g.words.length === 0) return void out.push(`${gat}.words must be a non-empty array`);
      const flat: { levels: number[] }[] = [];
      g.words.forEach((w: unknown, wi: number) => {
        const wat = `${gat}.words[${wi}]`;
        if (!isObj(w) || !isStr(w.text) || !Array.isArray(w.syllables) || w.syllables.length === 0) {
          return void out.push(`${wat} needs text and syllables`);
        }
        w.syllables.forEach((y: unknown, yi: number) => {
          const yat = `${wat}.syllables[${yi}]`;
          if (!isObj(y)) return void out.push(`${yat} is not an object`);
          if (!isStr(y.text)) out.push(`${yat}.text missing`);
          if (!isStr(y.ipa)) out.push(`${yat}.ipa missing (run npm run build:lessons)`);
          const lv = y.levels;
          if (!Array.isArray(lv) || lv.length < 1 || lv.length > 2 || lv.some((n) => typeof n !== "number" || n < 1 || n > 4)) {
            out.push(`${yat}.levels must be 1 or 2 numbers between 1 and 4`);
          } else flat.push({ levels: lv as number[] });
        });
      });
      const n = g.nucleus;
      const words = g.words as { syllables?: unknown[] }[];
      const nw = isObj(n) ? (n.word as number) : NaN;
      const ns = isObj(n) ? (n.syllable as number) : NaN;
      const inRange =
        Number.isInteger(nw) && Number.isInteger(ns) && nw >= 0 && nw < words.length && ns >= 0 && ns < (words[nw].syllables?.length ?? 0);
      if (!inRange) return void out.push(`${gat}.nucleus is outside the group`);
      const total = words.reduce((n, w) => n + (w.syllables?.length ?? 0), 0);
      // only compare levels when every syllable was readable (otherwise the errors above already say what is wrong)
      if ((g.pattern === "2-3-1" || g.pattern === "2-3" || g.pattern === "2-3-2" || g.pattern === "3-1") && flat.length === total) {
        let idx = 0;
        for (let wi = 0; wi < nw; wi++) idx += words[wi].syllables?.length ?? 0;
        idx += ns;
        const want =
          g.pattern === "2-3"
            ? levelsForRisingGroup(flat.length, idx)
            : g.pattern === "2-3-2"
              ? levelsForNonFinalGroup(flat.length, idx)
              : g.pattern === "3-1"
                ? levelsForFallingTag(flat.length, idx)
              : levelsForGroup(flat.length, idx);
        if (flat.some((f, k) => f.levels.join() !== want[k].join())) {
          out.push(`${gat}: levels do not follow ${g.pattern} around the nucleus`);
        }
      }
    });
  });
  return out;
}

/** Validate and type a lesson file. Throws with every problem listed. */
export function parseLesson(data: unknown): LessonContent {
  const problems = lessonProblems(data);
  if (problems.length > 0) throw new Error(`Invalid lesson content:\n- ${problems.join("\n- ")}`);
  return data as LessonContent;
}

/** The lesson content for `unitId`/`lessonId`, or undefined when there is none (unknown ids never throw). */
export function loadLesson(unitId: string, lessonId: string): LessonContent | undefined {
  const raw = Object.hasOwn(REGISTRY, `${unitId}/${lessonId}`) ? REGISTRY[`${unitId}/${lessonId}`] : undefined;
  if (raw === undefined) return undefined;
  const lesson = parseLesson(raw);
  return lesson.id === lessonId && lesson.unit === unitId ? lesson : undefined;
}

/** A course sentence by its id, searching every lesson (the server uses it so clients can't send their own sentences). */
export function findSentence(sentenceId: string): LessonContent["sentences"][number] | undefined {
  for (const key of Object.keys(REGISTRY)) {
    const [unitId, lessonId] = key.split("/");
    const found = loadLesson(unitId, lessonId)?.sentences.find((s) => s.id === sentenceId);
    if (found) return found;
  }
  return undefined;
}

/** All registered `unit/lesson` keys (used by tests to check every course lesson has content). */
export function contentKeys(): string[] {
  return Object.keys(REGISTRY);
}
